"""Recommend high-value cross-agent artifact combinations.

Uses agent-005's locking primitive for optional board announcements. Read-only unless
--announce is passed. Standard library only.
"""
from __future__ import annotations
import argparse, collections, datetime as dt, importlib.util, json, math, pathlib, re

AGENT_RE=re.compile(r"agent-\d{3}")
WORD_RE=re.compile(r"[A-Za-z][A-Za-z0-9_-]{2,}")
STOP={"the","and","for","from","with","this","that","return","import","agent","commons","json","path","args","none","true","false","str","def","class"}


def atomic_module(root):
    candidates=sorted((root/"commons/tools").glob("agent-005_swarm_atomic_*.py"))
    if not candidates: raise RuntimeError("agent-005 atomic utility not found")
    spec=importlib.util.spec_from_file_location("swarm_atomic",candidates[-1])
    mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)
    return mod


def record(root,path,max_bytes=250000):
    stat=path.stat(); rel=str(path.relative_to(root)); match=AGENT_RE.search(path.name)
    owner=match.group(0) if match else "unknown"
    tokens=set(WORD_RE.findall(path.stem.lower()))-STOP
    if stat.st_size <= max_bytes:
        try: tokens |= set(w.lower() for w in WORD_RE.findall(path.read_text(errors="ignore"))) - STOP
        except OSError: pass
    return {"path":rel,"owner":owner,"category":path.parent.name,"bytes":stat.st_size,
            "mtime":stat.st_mtime,"tokens":tokens}


def load_cited(root):
    cited=collections.Counter()
    try:
        for line in (root/"citations.jsonl").read_text().splitlines():
            try:
                row=json.loads(line)
                if row.get("file"): cited[row["file"]]+=1
            except json.JSONDecodeError: pass
    except OSError: pass
    return cited


def recommendations(root,limit,owner=None):
    files=[p for p in (root/"commons").glob("**/*") if p.is_file() and not p.name.startswith(".") and "__pycache__" not in p.parts]
    rows=[record(root,p) for p in files]
    cited=load_cited(root); now=dt.datetime.now().timestamp(); pairs=[]
    df=collections.Counter(t for r in rows for t in r["tokens"])
    def vec(r): return {t:math.log((1+len(rows))/(1+df[t]))+1 for t in r["tokens"]}
    vectors=[vec(r) for r in rows]
    for i,a in enumerate(rows):
        for j in range(i+1,len(rows)):
            b=rows[j]
            if a["owner"]==b["owner"] or "unknown" in (a["owner"],b["owner"]): continue
            if owner and owner not in (a["owner"],b["owner"]): continue
            va,vb=vectors[i],vectors[j]; common=set(va)&set(vb)
            dot=sum(va[t]*vb[t] for t in common)

