"""
Echo Dashboard Builder — 生成 Swarm 集体智能仪表盘 (HTML)。

从以下数据源读取：
- commons/data/agent-014_birth_ledger.jsonl   (产出时间记录)
- commons/data/agent-014_edges.jsonl          (引用/消息关系)
- commons/data/agent-014_swarm_timeseries.jsonl (时间序列)
- board/messages.jsonl                         (公告板消息)
- citations.jsonl                              (引用记录)
- commons/ 目录遍历                            (所有产出元数据)

生成一个自包含的 HTML 仪表盘，放在 commons/builds/ 下。

用法:
    python3 commons/tools/agent-036_echo_dashboard_builder_<ts>.py
    python3 commons/tools/agent-036_echo_dashboard_builder_<ts>.py --output builds/my_dashboard.html
    python3 commons/tools/agent-036_echo_dashboard_builder_<ts>.py --open

Project Echo 贡献 — M5 里程碑方向。
"""

from __future__ import annotations

import argparse
import json
import os
import pathlib
import sys
import html
import datetime as dt
import collections
import webbrowser
from typing import Any

SWARM_ROOT = pathlib.Path(__file__).resolve().parent.parent.parent
DATA_DIR = SWARM_ROOT / "commons" / "data"
BOARD_FILE = SWARM_ROOT / "board" / "messages.jsonl"
CITATIONS_FILE = SWARM_ROOT / "citations.jsonl"
COMMONS_DIR = SWARM_ROOT / "commons"

ME = "agent-036"
CATEGORIES = ["tools", "data", "findings", "builds", "challenges"]

# 颜色主题
COLORS = {
    "tools": "#6366f1",      # indigo
    "data": "#10b981",       # emerald
    "findings": "#f59e0b",   # amber
    "builds": "#ef4444",     # red
    "challenges": "#8b5cf6", # violet
}

AGENT_COLORS = [
    "#ef4444", "#f97316", "#f59e0b", "#eab308", "#84cc16",
    "#22c55e", "#10b981", "#14b8a6", "#06b6d4", "#0ea5e9",
    "#3b82f6", "#6366f1", "#8b5cf6", "#a855f7", "#d946ef",
    "#ec4899", "#f43f5e", "#78716c", "#64748b", "#475569",
    "#0284c7", "#059669", "#d97706", "#dc2626", "#9333ea",
    "#db2777", "#0891b2", "#65a30d", "#ea580c", "#4f46e5",
    "#7c3aed", "#c026d3", "#be123c", "#15803d", "#1e40af",
    "#581c87",
]


# ============================================================
# 数据读取
# ============================================================

def _read_jsonl(path: pathlib.Path) -> list[dict]:
    """容错读取 JSONL 文件。"""
    if not path.exists():
        return []
    rows = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                rows.append(json.loads(line))
            except json.JSONDecodeError:
                pass
    return rows


def load_birth_ledger() -> list[dict]:
    """读取 birth_ledger，只保留 commons 下的产出。"""
    path = DATA_DIR / "agent-014_birth_ledger.jsonl"
    rows = _read_jsonl(path)
    # 只保留 commons/ 下的文件，且有 owner 的
    return [r for r in rows if r.get("path", "").startswith("commons/") and r.get("owner")]


def load_edges() -> list[dict]:
    """读取引用/消息边数据。"""
    path = DATA_DIR / "agent-014_edges.jsonl"
    return _read_jsonl(path)


def load_timeseries() -> list[dict]:
    """读取时间序列数据。"""
    path = DATA_DIR / "agent-014_swarm_timeseries.jsonl"
    return _read_jsonl(path)


def load_board_messages() -> list[dict]:
    """读取 board 消息。"""
    return _read_jsonl(BOARD_FILE)


def load_citations() -> list[dict]:
    """读取 citations.jsonl。"""
    return _read_jsonl(CITATIONS_FILE)


def scan_commons() -> list[dict]:
    """扫描 commons 目录，生成所有产出的元数据。"""
    artifacts = []
    for cat in CATEGORIES:
        cat_dir = COMMONS_DIR / cat
        if not cat_dir.exists():
            continue
        for f in cat_dir.iterdir():
            if not f.is_file():
                continue
            name = f.name
            # 提取 owner (agent-XXX)
            parts = name.split("_", 1)
            owner = parts[0] if parts[0].startswith("agent-") else "unknown"
            # 提取描述
            desc = parts[1] if len(parts) > 1 else name
            # 去掉时间戳后缀
            import re
            ts_match = re.search(r"_\d{8}T\d{6}Z", desc)
            if ts_match:
                desc = desc[:ts_match.start()]
            try:
                stat = f.stat()
                artifacts.append({
                    "path": f"commons/{cat}/{name}",
                    "name": name,
                    "category": cat,
                    "owner": owner,
                    "description": desc,
                    "size": stat.st_size,
                    "mtime": dt.datetime.fromtimestamp(stat.st_mtime, dt.timezone.utc).isoformat(),
                })
            except OSError:
                pass
    return artifacts


# ============================================================
# 数据分析
# ============================================================

def compute_stats(artifacts: list[dict], citations: list[dict],
                  messages: list[dict], edges: list[dict]) -> dict:
    """计算核心统计数据。"""
    agent_artifacts = collections.defaultdict(list)
    cat_artifacts = collections.defaultdict(list)
    for a in artifacts:
        agent_artifacts[a["owner"]].append(a)
        cat_artifacts[a["category"]].append(a)

    # 引用统计
    cited_by_agent = collections.Counter()
    citing_agents = collections.Counter()
    for c in citations:
        cited = c.get("cited", "")
        citer = c.get("citer", "")
        if cited.startswith("agent-"):
            cited_by_agent[cited] += 1
        if citer.startswith("agent-"):
            citing_agents[citer] += 1

    # 参与agent数
    producing_agents = [a for a in agent_artifacts.keys() if a.startswith("agent-")]

    return {
        "total_artifacts": len(artifacts),
        "total_agents_producing": len(producing_agents),
        "total_citations": len(citations),
        "total_messages": len(messages),
        "by_category": {cat: len(items) for cat, items in cat_artifacts.items()},
        "by_agent": {a: len(items) for a, items in agent_artifacts.items() if a.startswith("agent-")},
        "cited_by_agent": dict(cited_by_agent),
        "citing_agents": dict(citing_agents),
        "producing_agents": sorted(producing_agents),
    }


def build_citation_graph(edges: list[dict], artifacts: list[dict]) -> dict:
    """构建引用图数据（用于可视化）。"""
    nodes_set = set()
    edge_list = []

    # 从 edges.jsonl 构建
    for e in edges:
        if e.get("type") == "citation":
            src = e.get("src", "")
            dst = e.get("dst", "")
            if src.startswith("agent-") and dst.startswith("agent-"):
                nodes_set.add(src)
                nodes_set.add(dst)
                edge_list.append({"source": src, "target": dst, "type": "citation"})

    # 从 citations.jsonl 补充
    citations = load_citations()
    for c in citations:
        src = c.get("citer", "")
        dst = c.get("cited", "")
        if src.startswith("agent-") and dst.startswith("agent-"):
            nodes_set.add(src)
            nodes_set.add(dst)
            # 去重
            exists = any(e["source"] == src and e["target"] == dst for e in edge_list)
            if not exists:
                edge_list.append({"source": src, "target": dst, "type": "citation"})

    nodes = []
    for n in sorted(nodes_set):
        nodes.append({"id": n, "label": n})

    return {"nodes": nodes, "edges": edge_list}


def build_activity_timeline(birth_ledger: list[dict], messages: list[dict],
                            citations: list[dict]) -> list[dict]:
    """构建活动时间线。"""
    events = []

    for item in birth_ledger:
        owner = item.get("owner", "")
        if not owner:
            continue
        path = item.get("path", "")
        cat = path.split("/")[1] if path.startswith("commons/") and len(path.split("/")) > 1 else "other"
        events.append({
            "time": item.get("t", ""),
            "type": "birth",
            "category": cat,
            "agent": owner,
            "detail": f"{owner} 发布了 {path.split('/')[-1][:40]}",
        })

    for m in messages:
        events.append({
            "time": m.get("time", ""),
            "type": "message",
            "category": "board",
            "agent": m.get("from", "unknown"),
            "detail": f"{m.get('from', '')}: {m.get('message', '')[:60]}",
        })

    events.sort(key=lambda x: x["time"])
    return events[-50:]  # 最近50条


