def _color_for_agent(agent_id: str) -> str:
    """根据 agent id 分配稳定颜色。"""
    import re
    m = re.search(r"agent-(\d+)", agent_id)
    if m:
        idx = int(m.group(1)) % len(AGENT_COLORS)
        return AGENT_COLORS[idx]
    return "#6b7280"


def generate_html(stats: dict, graph: dict, timeline: list[dict],
                  artifacts: list[dict], messages: list[dict]) -> str:
    """生成完整的 HTML 仪表盘。"""

    # 排序的列表
    top_producers = sorted(stats["by_agent"].items(), key=lambda x: x[1], reverse=True)[:15]
    top_cited = sorted(stats["cited_by_agent"].items(), key=lambda x: x[1], reverse=True)[:15]

    # 分类统计
    cat_data = stats["by_category"]

    now = dt.datetime.now(dt.timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")

    # 生成节点 JSON
    nodes_json = json.dumps(graph["nodes"])
    edges_json = json.dumps(graph["edges"])

    # 生成时间线数据
    timeline_json = json.dumps(timeline)

    # 消息列表
    messages_sorted = sorted(messages, key=lambda x: x.get("time", ""), reverse=True)[:20]
    messages_html = ""
    for m in messages_sorted:
        msg_from = html.escape(m.get("from", "unknown"))
        msg_to = html.escape(m.get("to", "all"))
        msg_text = html.escape(m.get("message", ""))
        msg_time = html.escape(m.get("time", ""))
        color = _color_for_agent(msg_from)
        messages_html += f'''
        <div class="msg-item">
            <div class="msg-header">
                <span class="msg-from" style="color:{color}">● {msg_from}</span>
                <span class="msg-to">→ {msg_to}</span>
                <span class="msg-time">{msg_time}</span>
            </div>
            <div class="msg-text">{msg_text}</div>
        </div>'''

    # 产出分类表格
    artifacts_by_cat = collections.defaultdict(list)
    for a in artifacts:
        artifacts_by_cat[a["category"]].append(a)

    artifacts_html = ""
    for cat in CATEGORIES:
        items = sorted(artifacts_by_cat.get(cat, []), key=lambda x: x["mtime"], reverse=True)
        if not items:
            continue
        cat_color = COLORS.get(cat, "#6b7280")
        artifacts_html += f'''
        <div class="cat-section">
            <h3 style="color:{cat_color}">{cat.capitalize()} ({len(items)})</h3>
            <div class="artifact-list">'''
        for a in items[:10]:
            owner = html.escape(a["owner"])
            name = html.escape(a["name"])
            desc = html.escape(a["description"])
            size = a["size"]
            color = _color_for_agent(owner)
            artifacts_html += f'''
                <div class="artifact-item">
                    <span class="artifact-owner" style="color:{color}">{owner}</span>
                    <span class="artifact-desc" title="{name}">{desc}</span>
                    <span class="artifact-size">{size}B</span>
                </div>'''
        if len(items) > 10:
            artifacts_html += f'<div class="more">... 还有 {len(items) - 10} 个</div>'
        artifacts_html += '</div></div>'

    # Top producers bar chart (纯 CSS)
    max_prod = max((n for _, n in top_producers), default=1)
    producers_html = ""
    for agent, count in top_producers:
        pct = (count / max_prod) * 100
        color = _color_for_agent(agent)
        producers_html += f'''
        <div class="bar-row">
            <span class="bar-label">{agent}</span>
            <div class="bar-track">
                <div class="bar-fill" style="width:{pct}%;background:{color}"></div>
            </div>
            <span class="bar-value">{count}</span>
        </div>'''

    # Top cited bar chart
    max_cited = max((n for _, n in top_cited), default=1)
    cited_html = ""
    if top_cited:
        for agent, count in top_cited:
            pct = (count / max_cited) * 100
            color = _color_for_agent(agent)
            cited_html += f'''
            <div class="bar-row">
                <span class="bar-label">{agent}</span>
                <div class="bar-track">
                    <div class="bar-fill" style="width:{pct}%;background:{color}"></div>
                </div>
                <span class="bar-value">{count}</span>
            </div>'''
    else:
        cited_html = '<div class="empty">暂无引用数据</div>'

    # 分类统计卡片
    cat_cards_html = ""
    for cat in CATEGORIES:
        count = cat_data.get(cat, 0)
        color = COLORS.get(cat, "#6b7280")
        cat_cards_html += f'''
        <div class="stat-mini" style="border-left:4px solid {color}">
            <div class="stat-mini-val" style="color:{color}">{count}</div>
            <div class="stat-mini-label">{cat.capitalize()}</div>
        </div>'''

    return f"""<!DOCTYPE html>
