<script>
// ============================================================
// 简单的力导向图（纯 JS，无依赖）
// ============================================================
(function() {{
    const nodes = {nodes_json};
    const edges = {edges_json};
    const timeline = {timeline_json};

    const container = document.getElementById('graph-container');
    if (!container || nodes.length === 0) {{
        container.innerHTML = '<div class="empty">暂无引用关系数据</div>';
    }} else {{
        const width = container.clientWidth;
        const height = 350;
        const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
        svg.setAttribute('viewBox', `0 0 ${{width}} ${{height}}`);
        container.appendChild(svg);

        // 颜色映射
        function agentColor(id) {{
            const m = id.match(/agent-(\\d+)/);
            const colors = {json.dumps(AGENT_COLORS)};
            if (m) return colors[parseInt(m[1]) % colors.length];
            return '#6b7280';
        }}

        // 初始化节点位置（圆形分布）
        const cx = width / 2, cy = height / 2;
        const radius = Math.min(width, height) * 0.35;
        nodes.forEach((n, i) => {{
            const angle = (i / nodes.length) * 2 * Math.PI - Math.PI / 2;
            n.x = cx + radius * Math.cos(angle);
            n.y = cy + radius * Math.sin(angle);
            n.vx = 0; n.vy = 0;
        }});

        // 节点度数
        const degree = {{}};
        nodes.forEach(n => degree[n.id] = 0);
        edges.forEach(e => {{
            degree[e.source] = (degree[e.source] || 0) + 1;
            degree[e.target] = (degree[e.target] || 0) + 1;
        }});

        // 创建 SVG 元素
        const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
        svg.appendChild(defs);

        const gEdges = document.createElementNS('http://www.w3.org/2000/svg', 'g');
        svg.appendChild(gEdges);
        const gNodes = document.createElementNS('http://www.w3.org/2000/svg', 'g');
        svg.appendChild(gNodes);

        // 边
        const edgeElems = edges.map(e => {{
            const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
            line.setAttribute('stroke', '#475569');
            line.setAttribute('stroke-width', '1');
            line.setAttribute('stroke-opacity', '0.4');
            line.setAttribute('marker-end', 'url(#arrow)');
            gEdges.appendChild(line);
            return {{ elem: line, data: e }};
        }});

        // 节点
        const nodeElems = nodes.map(n => {{
            const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
            g.setAttribute('class', 'graph-node');
            g.setAttribute('transform', `translate(${{n.x}},${{n.y}})`);

            const r = 6 + (degree[n.id] || 0) * 2;
            const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
            circle.setAttribute('r', r);
            circle.setAttribute('fill', agentColor(n.id));
            g.appendChild(circle);

            const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
            text.textContent = n.id.replace('agent-', '#');
            text.setAttribute('y', r + 12);
            text.setAttribute('font-size', '9');
            g.appendChild(text);

            gNodes.appendChild(g);
            return {{ elem: g, data: n, radius: r }};
        }});

        // 力导向模拟
        function simulate() {{
            const repulsion = 800;
            const attraction = 0.008;
            const damping = 0.85;
            const centerPull = 0.002;
            const iterations = 150;

            for (let iter = 0; iter < iterations; iter++) {{
                // 排斥力
                for (let i = 0; i < nodes.length; i++) {{
                    for (let j = i + 1; j < nodes.length; j++) {{
                        const dx = nodes[j].x - nodes[i].x;
                        const dy = nodes[j].y - nodes[i].y;
                        const dist2 = dx*dx + dy*dy;
                        if (dist2 < 1) continue;
                        const dist = Math.sqrt(dist2);
                        const force = repulsion / dist2;
                        const fx = (dx / dist) * force;
                        const fy = (dy / dist) * force;
                        nodes[i].vx -= fx;
                        nodes[i].vy -= fy;
                        nodes[j].vx += fx;
                        nodes[j].vy += fy;
                    }}
                }}

                // 吸引力（边）
                edges.forEach(e => {{
                    const si = nodes.findIndex(n => n.id === e.source);
                    const ti = nodes.findIndex(n => n.id === e.target);
                    if (si < 0 || ti < 0) return;
                    const dx = nodes[ti].x - nodes[si].x;
                    const dy = nodes[ti].y - nodes[si].y;
                    const dist = Math.sqrt(dx*dx + dy*dy);
                    if (dist < 1) return;
                    const force = dist * attraction;
                    const fx = (dx / dist) * force;
                    const fy = (dy / dist) * force;
                    nodes[si].vx += fx;
                    nodes[si].vy += fy;
                    nodes[ti].vx -= fx;
                    nodes[ti].vy -= fy;
                }});

                // 中心拉力
                nodes.forEach(n => {{
                    n.vx += (cx - n.x) * centerPull;
                    n.vy += (cy - n.y) * centerPull;
                }});

                // 阻尼 + 更新位置
                nodes.forEach(n => {{
                    n.vx *= damping;
                    n.vy *= damping;
                    n.x += n.vx;
                    n.y += n.vy;
                    // 边界约束
                    const pad = 30;
                    n.x = Math.max(pad, Math.min(width - pad, n.x));
                    n.y = Math.max(pad, Math.min(height - pad, n.y));
                }});

                // 每 5 帧更新一次显示
                if (iter % 5 === 0) {{
                    updatePositions();
                }}
            }}
            updatePositions();
        }}

        function updatePositions() {{
            nodeElems.forEach((ne, i) => {{
                ne.elem.setAttribute('transform', `translate(${{nodes[i].x}},${{nodes[i].y}})`);
            }});
            edgeElems.forEach(ee => {{
                const si = nodes.findIndex(n => n.id === ee.data.source);
                const ti = nodes.findIndex(n => n.id === ee.data.target);
                if (si < 0 || ti < 0) return;
                ee.elem.setAttribute('x1', nodes[si].x);
                ee.elem.setAttribute('y1', nodes[si].y);
                ee.elem.setAttribute('x2', nodes[ti].x);
                ee.elem.setAttribute('y2', nodes[ti].y);
            }});
        }}

        // 启动动画
        let frame = 0;
        function animate() {{
            if (frame < 30) {{
                simulate();
                frame++;
                requestAnimationFrame(animate);
            }}
        }}
        animate();
    }}

    // 时间线渲染
    const tlContainer = document.getElementById('timeline');
    if (tlContainer && timeline.length > 0) {{
        timeline.slice().reverse().forEach(e => {{
            const div = document.createElement('div');
            div.className = 'timeline-item';
            div.setAttribute('data-type', e.type);
            div.innerHTML = `
                <div class="timeline-time">${{e.time}}</div>
                <div class="timeline-detail">${{e.detail}}</div>
            `;
            tlContainer.appendChild(div);
        }});
    }}
}})();
</script>
</body>
</html>"""


