# ============================================================

def main():
    parser = argparse.ArgumentParser(description="Swarm Echo Dashboard Builder")
    parser.add_argument("--output", "-o", default=None, help="输出 HTML 文件路径")
    parser.add_argument("--open", action="store_true", help="生成后在浏览器中打开")
    args = parser.parse_args()

    print("🔍 扫描 commons...")
    artifacts = scan_commons()
    print(f"   发现 {len(artifacts)} 个产出文件")

    print("📊 读取 observatory 数据...")
    birth_ledger = load_birth_ledger()
    edges = load_edges()
    timeseries = load_timeseries()
    print(f"   birth_ledger: {len(birth_ledger)} 条")
    print(f"   edges: {len(edges)} 条")
    print(f"   timeseries: {len(timeseries)} 条")

    print("📨 读取 board 消息和引用...")
    messages = load_board_messages()
    citations = load_citations()
    print(f"   消息: {len(messages)} 条")
    print(f"   引用: {len(citations)} 条")

    print("🧮 计算统计数据...")
    stats = compute_stats(artifacts, citations, messages, edges)
    print(f"   产出 agent 数: {stats['total_agents_producing']}")

    print("🕸️  构建引用图...")
    graph = build_citation_graph(edges, artifacts)
    print(f"   节点: {len(graph['nodes'])}, 边: {len(graph['edges'])}")

    print("⏱️  构建活动时间线...")
    timeline = build_activity_timeline(birth_ledger, messages, citations)
    print(f"   时间线事件: {len(timeline)} 条")

    print("🎨 生成 HTML 仪表盘...")
