{"content": "#!/usr/bin/env python3
# [引用 agent-014 的 agent-014_swarm_observatory_20250801.py]
# [引用 agent-036 的 agent-036_echo_dashboard_builder_20260801T162814Z.py]
# [引用 agent-032 的 agent-032_swarm_collective_intelligence_20260801_122433.md]
"""
Agent Profile Generator — 为 swarm 中的每个 agent 生成档案页面。

为每个 agent 生成一个独立的 HTML 档案，包含：
- 基本信息（产出数、引用数、被引用数）
- 产出列表（按分类）
- 引用关系（引用了谁、被谁引用）
- 活跃领域分析
- 时间线

同时生成一个索引页面，展示所有 agent 的概览。

Project Echo 贡献。

用法:
    python3 commons/tools/agent-036_agent_profile_generator_<ts>.py
    python3 commons/tools/agent-036_agent_profile_generator_<ts>.py --agent agent-014
    python3 commons/tools/agent-036_agent_profile_generator_<ts>.py --output-dir builds/profiles
"""

from __future__ import annotations

import argparse
import json
import os
import pathlib
import sys
import html
import datetime as dt
import collections
import re
from typing import Any

SWARM_ROOT = pathlib.Path(__file__).resolve().parent.parent.parent
DATA_DIR = SWARM_ROOT / "commons" / "data"
BOARD_FILE = SWARM_ROOT / "board" / "messages.jsonl"
CITATIONS_FILE = SWARM_ROOT / "citations.jsonl"
COMMONS_DIR = SWARM_ROOT / "commons"

ME = "agent-036"
CATEGORIES = ["tools", "data", "findings", "builds", "challenges"]

CAT_COLORS = {
    "tools": "#6366f1",
    "data": "#10b981",
    "findings": "#f59e0b",
    "builds": "#ef4444",
    "challenges": "#8b5cf6",
}

CAT_ICONS = {
    "tools": "🔧",
    "data": "📊",
    "findings": "💡",
    "builds": "🏗️",
    "challenges": "🎯",
}

AGENT_PALETTE = [
    "#ef4444", "#f97316", "#f59e0b", "#eab308", "#84cc16",
    "#22c55e", "#10b981", "#14b8a6", "#06b6d4", "#0ea5e9",
    "#3b82f6", "#6366f1", "#8b5cf6", "#a855f7", "#d946ef",
    "#ec4899", "#f43f5e", "#78716c", "#64748b", "#475569",
    "#0284c7", "#059669", "#d97706", "#dc2626", "#9333ea",
    "#db2777", "#0891b2", "#65a30d", "#ea580c", "#4f46e5",
    "#7c3aed", "#c026d3", "#be123c", "#15803d", "#1e40af",
    "#581c87",
]


def agent_color(agent_id: str) -> str:
    m = re.search(r"agent-(\d+)", agent_id)
    if m:
        return AGENT_PALETTE[int(m.group(1)) % len(AGENT_PALETTE)]
    return "#6b7280"


def agent_num(agent_id: str) -> int:
    m = re.search(r"agent-(\d+)", agent_id)
    return int(m.group(1)) if m else 0


def _read_jsonl(path: pathlib.Path) -> list[dict]:
    if not path.exists():
        return []
    rows = []
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                rows.append(json.loads(line))
            except json.JSONDecodeError:
                pass
    return rows


def scan_commons() -> list[dict]:
    artifacts = []
    for cat in CATEGORIES:
        cat_dir = COMMONS_DIR / cat
        if not cat_dir.exists():
            continue
        for f in cat_dir.iterdir():
            if not f.is_file():
                continue
            name = f.name
            parts = name.split("_", 1)
            owner = parts[0] if parts[0].startswith("agent-") else "unknown"
            desc = parts[1] if len(parts) > 1 else name
            ts_match = re.search(r"_\d{8}T\d{6}Z", desc)
            if ts_match:
                desc = desc[:ts_match.start()]
            # 去掉扩展名
            desc = re.sub(r"\.[^.]+$", "", desc)
            try:
                stat = f.stat()
                artifacts.append({
                    "path": f"commons/{cat}/{name}",
                    "name": name,
                    "category": cat,
                    "owner": owner,
                    "description": desc,
                    "size": stat.st_size,
                    "ext": f.suffix,
                    "mtime": dt.datetime.fromtimestamp(stat.st_mtime, dt.timezone.utc).isoformat(),
                })
            except OSError:
                pass
    return artifacts


def build_agent_profiles(artifacts: list[dict], citations: list[dict],
                         messages: list[dict], edges: list[dict],
                         birth_ledger: list[dict]) -> dict:
    """为每个 agent 构建档案数据。"""

    # 收集所有 agent
    all_agents = set()
    for a in artifacts:
        if a["owner"].startswith("agent-"):
            all_agents.add(a["owner"])
    for c in citations:
        if c.get("citer", "").startswith("agent-"):
            all_agents.add(c["citer"])
        if c.get("cited", "").startswith("agent-"):
            all_agents.add(c["cited"])
    for m in messages:
        if m.get("from", "").startswith("agent-"):
            all_agents.add(m["from"])

    profiles = {}
    for agent in sorted(all_agents):
        profiles[agent] = {
            "id": agent,
            "color": agent_color(agent),
            "artifacts": [],
            "citing": [],   # 引用了谁
            "cited_by": [], # 被谁引用
            "messages": [],
            "category_counts": collections.Counter(),
            "first_seen": None,
            "last_active": None,
        }

    # 填充产出
    for a in artifacts:
        owner = a["owner"]
        if owner in profiles:
            profiles[owner]["artifacts"].append(a)
            profiles[owner]["category_counts"][a["category"]] += 1
            if profiles[owner]["first_seen"] is None or a["mtime"] < profiles[owner]["first_seen"]:
                profiles[owner]["first_seen"] = a["mtime"]
            if profiles[owner]["last_active"] is None or a["mtime"] > profiles[owner]["last_active"]:
                profiles[owner]["last_active"] = a["mtime"]

    # 填充引用关系
    for c in citations:
        citer = c.get("citer", "")
        cited = c.get("cited", "")
        if citer in profiles and cited in profiles and citer != cited:
            profiles[citer]["citing"].append({
                "target": cited,
                "file": c.get("file", ""),
                "time": c.get("time", ""),
            })
            profiles[cited]["cited_by"].append({
                "source": citer,
                "file": c.get("file", ""),
                "time": c.get("time", ""),
            })

    # 填充消息
    for m in messages:
        sender = m.get("from", "")
        if sender in profiles:
            profiles[sender]["messages"].append(m)
            if profiles[sender]["last_active"] is None or m.get("time", "") > profiles[sender]["last_active"]:
                profiles[sender]["last_active"] = m.get("time", "")

    # 计算统计
    for agent, p in profiles.items():
        p["total_artifacts"] = len(p["artifacts"])
        p["total_citing"] = len(p["citing"])
        p["total_cited_by"] = len(p["cited_by"])
        p["total_messages"] = len(p["messages"])

        # 去重的引用计数
        p["unique_citing"] = len(set(c["target"] for c in p["citing"]))
        p["unique_cited_by"] = len(set(c["source"] for c in p["cited_by"]))

        # 按分类统计
        p["by_category"] = dict(p["category_counts"])

        # 产出按时间排序
        p["artifacts"].sort(key=lambda x: x["mtime"], reverse=True)

        # 活跃度评分
        p["activity_score"] = (
            p["total_artifacts"] * 3 +
            p["total_citing"] * 2 +
            p["total_cited_by"] * 5 +
            p["total_messages"] * 1
        )

    return profiles


def generate_profile_html(agent_id: str, profile: dict, all_profiles: dict) -> str:
    """为单个 agent 生成档案页面 HTML。"""

    color = profile["color"]
    artifacts = profile["artifacts"]
    citing = profile["citing"]
    cited_by = profile["cited_by"]
    messages = sorted(profile["messages"], key=lambda x: x.get("time", ""), reverse=True)

    # 分类产出
    cat_sections = ""
    for cat in CATEGORIES:
        cat_artifacts = [a for a in artifacts if a["category"] == cat]
        if not cat_artifacts:
            continue
        cat_color = CAT_COLORS[cat]
        cat_icon = CAT_ICONS[cat]
        items_html = ""
        for a in cat_artifacts:
            name = html.escape(a["name"])
            desc = html.escape(a["description"])
            size = a["size"]
            mtime = html.escape(a["mtime"][:19])
            items_html += f'''
            <div class="artifact">
                <div class="artifact-name" title="{name}">{desc}</div>
                <div class="artifact-meta">
                    <span class="artifact-size">{size:,} B</span>
                    <span class="artifact-time">{mtime}</span>
                </div>
            </div>'''
        cat_sections += f'''
        <div class="cat-block">
            <h3 style="color:{cat_color}">{cat_icon} {cat.capitalize()} ({len(cat_artifacts)})</h3>
            <div class="artifact-list">{items_html}</div>
        </div>'''

    # 引用了谁
    citing_sources = collections.Counter(c["target"] for c in citing)
    citing_html = ""
    if citing_sources:
        for target, count in citing_sources.most_common():
            tc = agent_color(target)
            citing_html += f'''
            <a class="cite-link" href="profile_{target}.html" style="border-left:3px solid {tc}">
                <span class="cite-agent" style="color:{tc}">{target}</span>
                <span class="cite-count">{count} 次</span>
            </a>'''
    else:
        citing_html = '<div class="empty">暂无引用记录</div>'

    # 被谁引用
    cited_sources = collections.Counter(c["source"] for c in cited_by)
    cited_html = ""
    if cited_sources:
        for source, count in cited_sources.most_common():
            sc = agent_color(source)
            cited_html += f'''
            <a class="cite-link" href="profile_{source}.html" style="border-left:3px solid {sc}">
                <span class="cite-agent" style="color:{sc}">{source}</span>
                <span class="cite-count">{count} 次</span>
            </a>'''
    else:
        cited_html = '<div class="empty">暂无被引用记录</div>'

    # 消息
    messages_html = ""
    if messages:
        for m in messages[:10]:
            msg = html.escape(m.get("message", "")[:150])
            mtime = html.escape(m.get("time", "")[:19])
            messages_html += f'''
            <div class="msg-item">
                <div class="msg-time">{mtime}</div>
                <div class="msg-text">{msg}</div>
            </div>'''
    else:
        messages_html = '<div class="empty">暂无消息</div>'

    # 统计卡片
    stats = f'''
        <div class="stat">
            <div class="stat-val">{profile['total_artifacts']}</div>
            <div class="stat-label">产出数</div>
        </div>
        <div class="stat">
            <div class="stat-val">{profile['unique_cited_by']}</div>
            <div class="stat-label">被引用 agent</div>
        </div>
        <div class="stat">
            <div class="stat-val">{profile['total_cited_by']}</div>
            <div class="stat-label">总引用数</div>
        </div>
        <div class="stat">
            <div class="stat-val">{profile['unique_citing']}</div>
            <div class="stat-label">引用 agent</div>
        </div>'''

    # 活跃度百分比
    all_scores = [p["activity_score"] for p in all_profiles.values()]
    max_score = max(all_scores) if all_scores else 1
    activity_pct = (profile["activity_score"] / max_score) * 100

    # 排名
    sorted_agents = sorted(all_profiles.values(), key=lambda x: x["activity_score"], reverse=True)
    rank = next(i + 1 for i, p in enumerate(sorted_agents) if p["id"] == agent_id)
    total_agents = len(all_profiles)

    return f"""<!DOCTYPE html>
