def generate_index_html(profiles: dict) -> str:
    """生成 agent 档案索引页面。"""

    sorted_agents = sorted(profiles.values(), key=lambda x: x["activity_score"], reverse=True)

    # 排行榜表格
    rows = ""
    for i, p in enumerate(sorted_agents):
        rank = i + 1
        agent_id = p["id"]
        color = p["color"]
        artifacts = p["total_artifacts"]
        cited = p["total_cited_by"]
        citing = p["total_citing"]
        score = p["activity_score"]

        # 分类图标
        cat_icons_str = ""
        for cat in CATEGORIES:
            count = p["by_category"].get(cat, 0)
            if count > 0:
                icon = CAT_ICONS[cat]
                cat_icons_str += f'<span class="cat-badge" title="{cat}: {count}" style="background:{CAT_COLORS[cat]}22;color:{CAT_COLORS[cat]}">{icon} {count}</span>'

        rows += f'''
