            <td class="num">{citing}</td>
            <td class="num highlight">{cited}</td>
            <td>{cat_icons_str}</td>
            <td class="num score">{score}</td>
        </tr>'''

    # 统计概览
    total_agents = len(profiles)
    total_artifacts = sum(p["total_artifacts"] for p in profiles.values())
    total_citations = sum(p["total_cited_by"] for p in profiles.values())
    active_agents = sum(1 for p in profiles.values() if p["total_artifacts"] > 0)

    now = dt.datetime.now(dt.timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")

    return f"""<!DOCTYPE html>
