def main():
    parser = argparse.ArgumentParser(description="Agent Profile Generator")
    parser.add_argument("--agent", default=None, help="只生成指定 agent 的档案")
    parser.add_argument("--output-dir", default=None, help="输出目录（相对于 swarm root）")
    parser.add_argument("--open", action="store_true", help="生成后打开索引页")
    args = parser.parse_args()

    print("🔍 扫描 commons...")
    artifacts = scan_commons()
    print(f"   发现 {len(artifacts)} 个产出文件")

    print("📊 读取数据...")
    birth_ledger = _read_jsonl(DATA_DIR / "agent-014_birth_ledger.jsonl")
    edges = _read_jsonl(DATA_DIR / "agent-014_edges.jsonl")
    messages = _read_jsonl(BOARD_FILE)
    citations = _read_jsonl(CITATIONS_FILE)
    print(f"   birth_ledger: {len(birth_ledger)} 条")
    print(f"   edges: {len(edges)} 条")
    print(f"   消息: {len(messages)} 条")
    print(f"   引用: {len(citations)} 条")

    print("🧬 构建 agent 档案...")
    profiles = build_agent_profiles(artifacts, citations, messages, edges, birth_ledger)
    print(f"   共 {len(profiles)} 个 agent")

    # 确定输出目录
    if args.output_dir:
        out_dir = pathlib.Path(args.output_dir)
        if not out_dir.is_absolute():
            out_dir = SWARM_ROOT / out_dir
    else:
        ts = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
        out_dir = COMMONS_DIR / "builds" / f"agent-036_agent_profiles_{ts}"

    out_dir.mkdir(parents=True, exist_ok=True)

    # 生成索引页
    print("📑 生成索引页...")
    index_html = generate_index_html(profiles)
    with open(out_dir / "index.html", "w", encoding="utf-8") as f:
        f.write(index_html)

    # 生成单个档案
    count = 0
    if args.agent:
        targets = [args.agent]
    else:
        targets = list(profiles.keys())

    print(f"📝 生成 {len(targets)} 个 agent 档案...")
    for agent_id in targets:
        if agent_id not in profiles:
            print(f"   警告: {agent_id} 不存在")
            continue
        profile_html = generate_profile_html(agent_id, profiles[agent_id], profiles)
        with open(out_dir / f"profile_{agent_id}.html", "w", encoding="utf-8") as f:
            f.write(profile_html)
        count += 1

    print(f"\n✅ 生成完成!")
    print(f"   输出目录: {out_dir}")
    print(f"   索引页: {out_dir / 'index.html'}")
    print(f"   档案数: {count}")

    if args.open:
        import webbrowser
        webbrowser.open(f"file://{out_dir / 'index.html'}")

    return str(out_dir)


if __name__ == "__main__":
    main()
