// ========== 工具函数 ==========
function getDelay() {
  // 速度 1-100 对应延迟 200ms - 1ms
  return 200 - (speedSlider.value - 1) * 2;
}

function generateArray() {
  const size = parseInt(sizeSlider.value);
  const type = arrayTypeSelect.value;
  array = [];

  for (let i = 0; i < size; i++) {
    array.push(i + 1);
  }

  if (type === 'random') {
    // Fisher-Yates shuffle
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
  } else if (type === 'reversed') {
    array.reverse();
  } else if (type === 'nearly') {
    // 先打乱，再几乎排序
    for (let i = array.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [array[i], array[j]] = [array[j], array[i]];
    }
    array.sort((a, b) => a - b);
    // 随机交换 10% 的元素
    const swapsNum = Math.floor(size * 0.1);
    for (let i = 0; i < swapsNum; i++) {
      const a = Math.floor(Math.random() * size);
      const b = Math.floor(Math.random() * size);
      [array[a], array[b]] = [array[b], array[a]];
    }
  }

  originalArray = [...array];
  comparisons = 0;
  swaps_count = 0;
  accesses = 0;
  swaps = 0;
  updateStats();
  renderBars();
  updateAlgoInfo();
}

function renderBars(highlights = {}) {
  const size = array.length;
  const maxVal = Math.max(...array);
  barsContainer.innerHTML = '';

  for (let i = 0; i < size; i++) {
    const bar = document.createElement('div');
    bar.className = 'bar';
    const height = (array[i] / maxVal) * 100;
    bar.style.height = height + '%';

    if (highlights.comparing && highlights.comparing.includes(i)) {
      bar.classList.add('comparing');
    }
    if (highlights.swapping && highlights.swapping.includes(i)) {
      bar.classList.add('swapping');
    }
    if (highlights.sorted && highlights.sorted.includes(i)) {
      bar.classList.add('sorted');
    }
    if (highlights.pivot === i) {
      bar.classList.add('pivot');
    }

    barsContainer.appendChild(bar);
  }
}

function updateStats() {
  document.getElementById('comparisons').textContent = comparisons.toLocaleString();
  document.getElementById('swaps').textContent = swaps.toLocaleString();
  document.getElementById('accesses').textContent = accesses.toLocaleString();
  if (startTime > 0 && isRunning) {
    document.getElementById('elapsed').textContent = (Date.now() - startTime) + 'ms';
  }
}

function updateAlgoInfo() {
  const algo = algorithmSelect.value;
  const info = algorithmInfo[algo];
  document.getElementById('algoContent').innerHTML = `
