function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// ========== 排序算法生成器 ==========

function* bubbleSortGen(arr) {
  const n = arr.length;
  const sorted = [];
  for (let i = 0; i < n - 1; i++) {
    let swapped = false;
    for (let j = 0; j < n - i - 1; j++) {
      comparisons++;
      accesses += 2;
      yield { comparing: [j, j + 1], sorted };
      if (arr[j] > arr[j + 1]) {
        [arr[j], arr[j + 1]] = [arr[j + 1], arr[j]];
        swaps++;
        accesses += 2;
        swapped = true;
        yield { swapping: [j, j + 1], sorted };
      }
    }
    sorted.push(n - i - 1);
    if (!swapped) break;
  }
  // 标记所有已排序
  const allSorted = [];
  for (let i = 0; i < n; i++) allSorted.push(i);
  yield { sorted: allSorted };
}

function* selectionSortGen(arr) {
  const n = arr.length;
  const sorted = [];
  for (let i = 0; i < n - 1; i++) {
    let minIdx = i;
    for (let j = i + 1; j < n; j++) {
      comparisons++;
      accesses += 2;
      yield { comparing: [minIdx, j], sorted };
      if (arr[j] < arr[minIdx]) {
        minIdx = j;
      }
    }
    if (minIdx !== i) {
      [arr[i], arr[minIdx]] = [arr[minIdx], arr[i]];
      swaps++;
      accesses += 2;
      yield { swapping: [i, minIdx], sorted };
    }
    sorted.push(i);
  }
  sorted.push(n - 1);
  yield { sorted };
}

function* insertionSortGen(arr) {
  const n = arr.length;
  const sorted = [0];
  for (let i = 1; i < n; i++) {
    let j = i;
    while (j > 0) {
      comparisons++;
      accesses += 2;
      yield { comparing: [j - 1, j], sorted };
      if (arr[j - 1] > arr[j]) {
        [arr[j - 1], arr[j]] = [arr[j], arr[j - 1]];
        swaps++;
        accesses += 2;
        yield { swapping: [j - 1, j], sorted };
        j--;
      } else {
        break;
      }
    }
    sorted.push(i);
  }
  yield { sorted };
}

function* mergeSortGen(arr) {
  const sortedIndices = new Set();
  yield* mergeSortHelper(arr, 0, arr.length - 1, sortedIndices);
  // 标记全部已排序
  const allSorted = [];
  for (let i = 0; i < arr.length; i++) allSorted.push(i);
  yield { sorted: allSorted };
}

function* mergeSortHelper(arr, left, right, sortedIndices) {
  if (left >= right) {
    sortedIndices.add(left);
    return;
  }
  const mid = Math.floor((left + right) / 2);
  yield* mergeSortHelper(arr, left, mid, sortedIndices);
  yield* mergeSortHelper(arr, mid + 1, right, sortedIndices);
  yield* merge(arr, left, mid, right, sortedIndices);
}

function* merge(arr, left, mid, right, sortedIndices) {
  const leftArr = arr.slice(left, mid + 1);
  const rightArr = arr.slice(mid + 1, right + 1);
  accesses += (right - left + 1);

  let i = 0, j = 0, k = left;

  while (i < leftArr.length && j < rightArr.length) {
    comparisons++;
    accesses += 2;
    yield { comparing: [left + i, mid + 1 + j], sorted: [...sortedIndices] };
    if (leftArr[i] <= rightArr[j]) {
      arr[k] = leftArr[i];
      swaps++;
      accesses++;
      i++;
    } else {
      arr[k] = rightArr[j];
      swaps++;
      accesses++;
      j++;
    }
    yield { swapping: [k], sorted: [...sortedIndices] };
    k++;
  }

  while (i < leftArr.length) {
    arr[k] = leftArr[i];
    swaps++;
    accesses++;
    yield { swapping: [k], sorted: [...sortedIndices] };
    i++;
    k++;
  }

  while (j < rightArr.length) {
    arr[k] = rightArr[j];
    swaps++;
    accesses++;
    yield { swapping: [k], sorted: [...sortedIndices] };
    j++;
    k++;
  }

  for (let idx = left; idx <= right; idx++) {
    sortedIndices.add(idx);
  }
}

function* quickSortGen(arr) {
  const sortedIndices = new Set();
  yield* quickSortHelper(arr, 0, arr.length - 1, sortedIndices);
  const allSorted = [];
  for (let i = 0; i < arr.length; i++) allSorted.push(i);
  yield { sorted: allSorted };
}

function* quickSortHelper(arr, low, high, sortedIndices) {
  if (low < high) {
    const pivotResult = yield* partition(arr, low, high, sortedIndices);
    const pi = pivotResult;
    sortedIndices.add(pi);
    yield* quickSortHelper(arr, low, pi - 1, sortedIndices);
    yield* quickSortHelper(arr, pi + 1, high, sortedIndices);
  } else if (low === high) {
    sortedIndices.add(low);
  }
}

function* partition(arr, low, high, sortedIndices) {
  const pivot = arr[high];
  accesses++;
  let i = low - 1;

  for (let j = low; j < high; j++) {
    comparisons++;
    accesses++;
    yield { comparing: [j, high], pivot: high, sorted: [...sortedIndices] };
    if (arr[j] < pivot) {
      i++;
      if (i !== j) {
        [arr[i], arr[j]] = [arr[j], arr[i]];
        swaps++;
        accesses += 2;
        yield { swapping: [i, j], pivot: high, sorted: [...sortedIndices] };
      }
    }
  }

  if (i + 1 !== high) {
    [arr[i + 1], arr[high]] = [arr[high], arr[i + 1]];
    swaps++;
    accesses += 2;
    yield { swapping: [i + 1, high], sorted: [...sortedIndices] };
  }

  return i + 1;
}

function* heapSortGen(arr) {
  const n = arr.length;
  const sorted = [];

  // 建堆
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
    yield* heapify(arr, n, i, sorted);
  }

  // 一个个取出元素
  for (let i = n - 1; i > 0; i--) {
    [arr[0], arr[i]] = [arr[i], arr[0]];
    swaps++;
    accesses += 2;
    sorted.unshift(i);
    yield { swapping: [0, i], sorted };
    yield* heapify(arr, i, 0, sorted);
  }

  sorted.unshift(0);
  yield { sorted };
}

function* heapify(arr, n, i, sorted) {
  let largest = i;
  const left = 2 * i + 1;
  const right = 2 * i + 2;

  if (left < n) {
    comparisons++;
    accesses += 2;
    yield { comparing: [largest, left], sorted };
    if (arr[left] > arr[largest]) {
      largest = left;
    }
  }

  if (right < n) {
    comparisons++;
    accesses += 2;
    yield { comparing: [largest, right], sorted };
    if (arr[right] > arr[largest]) {
      largest = right;
    }
  }

  if (largest !== i) {
    [arr[i], arr[largest]] = [arr[largest], arr[i]];
    swaps++;
    accesses += 2;
    yield { swapping: [i, largest], sorted };
    yield* heapify(arr, n, largest, sorted);
  }
}

// ========== 动画控制 ==========
async function runAnimation() {
  if (!generator) return;

  isRunning = true;
  isPaused = false;
  startTime = Date.now();
  startBtn.disabled = true;
  stepBtn.disabled = true;
  pauseBtn.disabled = false;

  const animate = async () => {
    while (isRunning && !isPaused) {
      const result = generator.next();
      if (result.done) {
        isRunning = false;
        startBtn.disabled = false;
        stepBtn.disabled = true;
        pauseBtn.disabled = true;
        updateStats();
        return;
      }
      renderBars(result.value);
      updateStats();
      await sleep(getDelay());
    }
  };

  await animate();
}

function stepOnce() {
  if (!generator) {
    initGenerator();
  }

  const result = generator.next();
  if (result.done) {
    isRunning = false;
    startBtn.disabled = false;
    stepBtn.disabled = true;
    pauseBtn.disabled = true;
    return;
  }
  renderBars(result.value);
  updateStats();
}

function initGenerator() {
  const algo = algorithmSelect.value;
  array = [...originalArray];
  comparisons = 0;
  swaps = 0;
  accesses = 0;
  startTime = Date.now();

  switch (algo) {
    case 'bubble': generator = bubbleSortGen(array); break;
    case 'selection': generator = selectionSortGen(array); break;
    case 'insertion': generator = insertionSortGen(array); break;
    case 'merge': generator = mergeSortGen(array); break;
    case 'quick': generator = quickSortGen(array); break;
    case 'heap': generator = heapSortGen(array); break;
  }
}

function startSort() {
  initGenerator();
  runAnimation();
}

function togglePause() {
  if (!isRunning) return;

  if (isPaused) {
    isPaused = false;
    pauseBtn.textContent = '⏸ 暂停';
    runAnimation();
  } else {
    isPaused = true;
    pauseBtn.textContent = '▶ 继续';
  }
}

function reset() {
  isRunning = false;
  isPaused = false;
  generator = null;
  startBtn.disabled = false;
  stepBtn.disabled = false;
  pauseBtn.disabled = true;
  pauseBtn.textContent = '⏸ 暂停';
  generateArray();
}

// ========== 事件监听 ==========
sizeSlider.addEventListener('input', () => {
  sizeVal.textContent = sizeSlider.value;
  if (!isRunning) generateArray();
});

algorithmSelect.addEventListener('change', () => {
  updateAlgoInfo();
  if (!isRunning) reset();
});

arrayTypeSelect.addEventListener('change', () => {
  if (!isRunning) generateArray();
});

startBtn.addEventListener('click', startSort);
stepBtn.addEventListener('click', stepOnce);
pauseBtn.addEventListener('click', togglePause);
resetBtn.addEventListener('click', reset);

// 更新时间显示
setInterval(() => {
  if (isRunning && startTime > 0) {
    document.getElementById('elapsed').textContent = (Date.now() - startTime) + 'ms';
  }
}, 50);

// 初始化
generateArray();
</script>
