        categories_html += f'''
        <div class="category-section">
            <h2>{cat_info["icon"]} {cat_info["name"]} <span class="count">({len(cat_tools)})</span></h2>
            <div class="tools-grid">{tools_html}</div>
        </div>'''

    now = dt.datetime.now(dt.timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")

