def main():
    parser = argparse.ArgumentParser(description="Swarm Tool Cheat Sheet Generator")
    parser.add_argument("--html-only", action="store_true", help="只打印 HTML 输出")
    parser.add_argument("--publish", action="store_true", help="发布到 builds/")
    parser.add_argument("--json-out", action="store_true", help="输出 JSON")
    args = parser.parse_args()

    print("🔍 扫描工具...")
    tools = scan_tools()
    print(f"   发现 {len(tools)} 个工具")

    # 分类统计
    cat_counts = collections.Counter()
    for t in tools:
        for cat in t["categories"]:
            cat_counts[cat] += 1

    print(f"   分类数: {len(cat_counts)}")
    for cat, count in cat_counts.most_common():
        cat_name = CATEGORIES.get(cat, {}).get("name", cat)
        print(f"     {cat_name}: {count}")

    if args.json_out:
        print(json.dumps({"tools": tools, "categories": {
            k: {"name": v["name"], "icon": v["icon"]}
            for k, v in CATEGORIES.items()
        }}, ensure_ascii=False, indent=2))
        return

    print("\n🎨 生成 HTML 速查表...")
    html_content = generate_html_cheatsheet(tools)

    if args.html_only:
        print(html_content)
        return

    if args.publish:
        ts = dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
        builds_dir = SWARM_ROOT / "commons" / "builds" / f"agent-036_tool_cheatsheet_{ts}"
        builds_dir.mkdir(parents=True, exist_ok=True)

        html_path = builds_dir / "index.html"
        with open(html_path, "w", encoding="utf-8") as f:
            f.write(html_content)

        # 同时保存 JSON 索引
        json_path = builds_dir / "tools_index.json"
        with open(json_path, "w", encoding="utf-8") as f:
            json.dump({"tools": tools, "categories": {
                k: {"name": v["name"], "icon": v["icon"]}
                for k, v in CATEGORIES.items()
            }}, f, ensure_ascii=False, indent=2)

        print(f"\n✅ 已发布:")
        print(f"   HTML: {html_path.relative_to(SWARM_ROOT)}")
        print(f"   JSON: {json_path.relative_to(SWARM_ROOT)}")
        print(f"   工具数: {len(tools)}")
        print(f"   HTML 大小: {html_path.stat().st_size:,} bytes")


if __name__ == "__main__":
    main()
